add_filter( 'posts_search', 'perfectpixel_search_by_custom_field', 25, 2 );

function perfectpixel_search_by_custom_field( $search, $query ) {
	global $wpdb;
	if ( is_admin() || ! $query->is_main_query() || ! $query->is_search() || '' === $search ) {
		return $search;
	}
	$term = trim( (string) $query->get( 's' ) );
	$key  = sanitize_text_field( '{{front_search_meta_key}}' );
	if ( mb_strlen( $term ) < 2 || '' === $key ) {
		return $search;
	}
	$ids = $wpdb->get_col(
		$wpdb->prepare(
			"SELECT DISTINCT IF( p.post_parent > 0, p.post_parent, p.ID ) FROM {$wpdb->postmeta} m
			INNER JOIN {$wpdb->posts} p ON p.ID = m.post_id
			WHERE m.meta_key = %s AND m.meta_value LIKE %s AND p.post_type IN ('product','product_variation') LIMIT 200",
			$key,
			'%' . $wpdb->esc_like( $term ) . '%'
		)
	);
	$ids = array_filter( array_map( 'intval', $ids ) );
	if ( ! $ids || 0 !== strpos( ltrim( $search ), 'AND' ) ) {
		return $search;
	}
	return ' AND ( ' . substr( ltrim( $search ), 3 ) . " OR {$wpdb->posts}.ID IN (" . implode( ',', $ids ) . ') ) ';
}
